 * Author: @bonheur-developer1 (https://tailwindflex.com/@bonheur-developer1)
 * Source: https://tailwindflex.com/@bonheur-developer1/bug-beach-day-heatwave
 * Attribution: Créé par @bonheur-developer1 sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function BugBeachDayHeatwave() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Hot Bugs Animation</title>

    <style>
        @keyframes fly {
            0% { transform: translate(0, 0) rotate(0deg); }
            25% { transform: translate(50px, -30px) rotate(5deg); }
            50% { transform: translate(100px, 0) rotate(0deg); }
            75% { transform: translate(150px, -20px) rotate(-5deg); }
            100% { transform: translate(200px, 0) rotate(0deg); }
        }
        @keyframes pulseHeat {
            0% { transform: scale(1); opacity: 0.7; }
            50% { transform: scale(1.2); opacity: 1; }
            100% { transform: scale(1); opacity: 0.7; }
        }
        @keyframes wiggle {
            0% { transform: rotate(-5deg); }
            50% { transform: rotate(5deg); }
            100% { transform: rotate(-5deg); }
        }
        .firefly { animation: fly 4s linear infinite; }
        .ladybug { animation: fly 5s linear infinite reverse; }
        .heat-wave { animation: pulseHeat 2s ease-in-out infinite; }
        .sun { animation: wiggle 8s ease-in-out infinite; }
    </style>
</head>
<body class="bg-orange-50 min-h-screen overflow-hidden">
    <div class="relative w-full h-screen">
        <!-- Sun -->
        <div class="sun absolute top-10 right-10 md:right-20 w-24 h-24 bg-yellow-400 rounded-full shadow-lg">
            <div class="absolute inset-0 rounded-full bg-orange-300 opacity-30 heat-wave"></div>
            <div class="absolute top-1/4 left-1/4 w-4 h-4 bg-orange-500 rounded-full"></div>
            <div class="absolute top-1/3 right-1/4 w-3 h-3 bg-orange-500 rounded-full"></div>
            <div class="absolute bottom-1/4 right-1/3 w-5 h-5 bg-orange-500 rounded-full"></div>
        </div>

        <!-- Hot ground -->
        <div class="absolute bottom-0 w-full h-32 bg-gradient-to-t from-orange-700 to-orange-500">
            <div class="absolute top-0 left-0 right-0 h-4 bg-orange-300 opacity-40 heat-wave"></div>
        </div>

        <!-- Firefly -->
        <div class="firefly absolute top-1/3 left-20">
            <div class="w-8 h-4 bg-yellow-400 rounded-full relative">
                <div class="absolute -top-1 -right-1 w-3 h-3 bg-yellow-200 rounded-full blur-sm heat-wave"></div>
                <div class="absolute top-1 left-1 w-1 h-1 bg-black rounded-full"></div>
                <div class="absolute top-1 left-3 w-1 h-1 bg-black rounded-full"></div>
            </div>
            <div class="w-8 h-1 bg-amber-700 mt-1"></div>
            <div class="flex justify-center gap-1 mt-1">
                <div class="w-6 h-2 bg-amber-900 rounded-full"></div>
            </div>
        </div>

        <!-- Ladybug -->
        <div class="ladybug absolute top-1/2 right-20">
            <div class="w-10 h-6 bg-red-600 rounded-full relative">
                <div class="absolute top-0 left-0 w-full h-3 bg-red-700 rounded-t-full"></div>
                <div class="absolute top-1 left-2 w-1 h-1 bg-black rounded-full"></div>
                <div class="absolute top-1 right-2 w-1 h-1 bg-black rounded-full"></div>
                <div class="absolute top-3 left-1 w-1 h-1 bg-black rounded-full"></div>
                <div class="absolute top-3 right-1 w-1 h-1 bg-black rounded-full"></div>
                <div class="absolute top-4 left-3 w-1 h-1 bg-black rounded-full"></div>
                <div class="absolute top-4 right-3 w-1 h-1 bg-black rounded-full"></div>
            </div>
            <div class="w-10 h-1 bg-black mt-1"></div>
            <div class="flex justify-center gap-1 mt-1">
                <div class="w-4 h-2 bg-black rounded-full"></div>
                <div class="w-4 h-2 bg-black rounded-full"></div>
            </div>
        </div>

        <!-- Heat waves text -->
        <div class="absolute top-1/4 left-1/2 transform -translate-x-1/2 text-center">
            <h1 class="text-4xl md:text-6xl font-bold text-orange-600 mb-2">HOT BUGS!</h1>
            <p class="text-xl text-orange-500 heat-wave">Summer is buzzing!</p>
        </div>

        <!-- Cracks in ground -->
        <div class="absolute bottom-32 left-0 right-0 h-2 bg-orange-800"></div>
        <div class="absolute bottom-32 left-1/4 w-1 h-8 bg-orange-800"></div>
        <div class="absolute bottom-32 right-1/3 w-1 h-6 bg-orange-800"></div>
        <div class="absolute bottom-32 left-1/2 w-2 h-10 bg-orange-800"></div>
    </div>
</body>
</html>" }} />
  );
}
